WITH sales AS ( SELECT i.i_category, d.d_year, d.d_month_seq, SUM(cs.cs_net_profit) AS total_profit, SUM(cs.cs_net_paid_inc_tax) AS total_sales, COUNT(*) AS sales_cnt FROM catalog_sales cs JOIN date_dim d ON cs.cs_sold_date_sk = d.d_date_sk JOIN item i ON cs.cs_item_sk = i.i_item_sk WHERE d.d_year = 2000 GROUP BY i.i_category, d.d_year, d.d_month_seq ), returns_cte AS ( SELECT i.i_category, d.d_year, d.d_month_seq, SUM(sr.sr_net_loss) AS total_loss, SUM(sr.sr_return_amt_inc_tax) AS total_return_amt, COUNT(*) AS return_cnt FROM store_returns sr JOIN date_dim d ON sr.sr_returned_date_sk = d.d_date_sk JOIN item i ON sr.sr_item_sk = i.i_item_sk WHERE d.d_year = 2000 GROUP BY i.i_category, d.d_year, d.d_month_seq ) SELECT s.i_category, s.d_year, s.d_month_seq, s.total_sales, s.total_profit, COALESCE(r.total_return_amt, 0) AS total_return_amt, s.total_profit - COALESCE(r.total_loss, 0) AS net_profit_after_returns, ROW_NUMBER() OVER (PARTITION BY s.d_month_seq ORDER BY (s.total_profit - COALESCE(r.total_loss, 0)) DESC) AS profit_rank_month FROM sales s LEFT JOIN returns_cte r ON s.i_category = r.i_category AND s.d_year = r.d_year AND s.d_month_seq = r.d_month_seq WHERE (s.total_profit - COALESCE(r.total_loss, 0)) > 0 ORDER BY s.d_year, s.d_month_seq, profit_rank_month LIMIT 100
